fonts:
@font-face {
  font-family: "Chengsheng Serif";
  src: url("/assets/fonts/chengsheng-serif.woff2") format("woff2");
  font-style: normal;
  font-weight: 500 700;
  font-display: swap;
}

reducedMotionBlock:
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
